192	async function handleCreateIdea(req: IncomingMessage, res: ServerResponse): Promise<void> {
193	  const chunks: Buffer[] = [];
194	  let size = 0;
195	  for await (const chunk of req as AsyncIterable<Buffer>) {
196	    size += chunk.length;
197	    if (size > MAX_BODY_BYTES) {
198	      respond(res, 400, { error: '请求体过大' });
199	      req.destroy();
200	      return;
201	    }
202	    chunks.push(chunk);
203	  }
204	  let payload: unknown;
205	  try {
206	    payload = JSON.parse(Buffer.concat(chunks).toString('utf8'));
207	  } catch {
208	    respond(res, 400, { error: '请求体不是有效的 JSON' });
209	    return;
210	  }
211	  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
212	    respond(res, 400, { error: '请求体必须是 JSON 对象' });
213	    return;
214	  }
215	  const body = payload as Record<string, unknown>;
216	  for (const field of ['title', 'description'] as const) {
217	    if (body[field] === undefined) { respond(res, 400, { error: `缺少必填字段 ${field}` }); return; }
218	    if (typeof body[field] !== 'string') { respond(res, 400, { error: `字段 ${field} 必须是字符串` }); return; }
219	  }
220	  if (body.scenario !== undefined && typeof body.scenario !== 'string') {
221	    respond(res, 400, { error: '字段 scenario 必须是字符串' });
222	    return;
223	  }
224	  const title = (body.title as string).trim();
225	  const description = body.description as string;
226	  const scenario = typeof body.scenario === 'string' ? body.scenario : '';
227	  if (!title) { respond(res, 400, { error: '标题去掉首尾空白后不能为空' }); return; }
228	  if (codePoints(title) > MAX_TITLE) { respond(res, 400, { error: `标题最多 ${MAX_TITLE} 个字符` }); return; }
229	  if (!description.trim()) { respond(res, 400, { error: '详细说明必须包含非空白内容' }); return; }
230	  if (codePoints(description) > MAX_DESCRIPTION) { respond(res, 400, { error: `详细说明最多 ${MAX_DESCRIPTION} 个字符` }); return; }
231	  if (codePoints(scenario) > MAX_SCENARIO) { respond(res, 400, { error: `使用场景最多 ${MAX_SCENARIO} 个字符` }); return; }
232	  const idea = {
233	    id: randomUUID(),
234	    title,
235	    description,
236	    scenario,
237	    createdAt: new Date().toISOString(),
238	  };
239	  let records: unknown[];
240	  try {
241	    records = readIdeas();
242	  } catch {
243	    respond(res, 500, { error: '无法读取已有意见数据，未保存新意见' });
244	    return;
245	  }
246	  records.unshift(idea);
247	  try {
248	    saveIdeas(records);
249	  } catch {
250	    respond(res, 500, { error: '保存意见失败，请稍后重试' });
251	    return;
252	  }
253	  respond(res, 201, { idea });
254	}
255	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
256	  let route: string;
257	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; } catch { respond(res, 400, { error: 'invalid request path' }); return; }
258	  if (!['/', '/health', '/api/ideas'].includes(route)) { respond(res, 404, { error: 'not found' }); return; }
259	  if (route === '/api/ideas') {
260	    if (req.method === 'POST') {
261	      handleCreateIdea(req, res).catch(() => {
262	        if (!res.headersSent) respond(res, 500, { error: '提交意见失败，请稍后重试' });
263	      });
264	      return;
265	    }
266	    if (req.method !== 'GET') { respond(res, 405, { error: 'method not allowed' }, { allow: 'GET, POST' }); return; }
267	    try {
268	      respond(res, 200, { [RESOURCE]: readIdeas() });
269	    } catch { respond(res, 500, { error: 'unable to read ideas' }); }
270	    return;
271	  }
272	  if (req.method !== 'GET') { respond(res, 405, { error: 'method not allowed' }); return; }
273	  if (route === '/') { respond(res, 200, PAGE, { html: true }); return; }
274	  respond(res, 200, { status: 'ok', product: PRODUCT });
275	});
276	server.once('error', (error: Error): void => { console.error(error.message); process.exitCode = 1; });
277	server.listen(port, host, (): void => {
278	  const address = server.address();
279	  if (address && typeof address !== 'string') {
280	    const displayedHost = address.address.includes(':') ? `[${address.address}]` : address.address;
281	    console.log(`${PRODUCT} listening on http://${displayedHost}:${address.port}`);
282	  }
283	});
284	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
285	  process.on(signal, (): void => { server.close(() => { process.exitCode = 0; }); server.closeIdleConnections(); });
286	}
