const fs = require('fs');
const vm = require('vm');
const http = require('http');

const PORT = process.env.PORT;
const html = await new Promise((resolve, reject) => {
  http.get(`http://127.0.0.1:${PORT}/`, (res) => {
    let body = '';
    res.on('data', (c) => (body += c));
    res.on('end', () => resolve(body));
  }).on('error', reject);
});
const code = html.match(/<script>([\s\S]*)<\/script>/)[1];

let passed = 0;
let failed = 0;
function assert(cond, msg) {
  if (cond) { passed++; }
  else { failed++; console.error('FAIL:', msg); }
}

function makeEl(tag) {
  const el = {
    tag, children: [], parent: null, handlers: {}, value: '', className: '', dateTime: '',
    _hidden: false, _text: '',
    get hidden() { return this._hidden; },
    set hidden(v) { this._hidden = !!v; },
    get textContent() { return this._text; },
    set textContent(v) { this._text = String(v); },
    append(...kids) { for (const k of kids) { k.parent = el; el.children.push(k); } },
    prepend(...kids) { for (const k of kids) k.parent = el; el.children.unshift(...kids); },
    after(kid) {
      const p = el.parent;
      kid.parent = p;
      const i = p.children.indexOf(el);
      p.children.splice(i + 1, 0, kid);
    },
    remove() {
      if (!el.parent) return;
      const i = el.parent.children.indexOf(el);
      if (i >= 0) el.parent.children.splice(i, 1);
      el.parent = null;
    },
    addEventListener(ev, fn) { el.handlers[ev] = fn; },
    reset() { el._reset = true; },
  };
  return el;
}

function env() {
  const els = {};
  const ids = ['idea-form', 'f-title', 'f-desc', 'f-scenario', 'error', 'success', 'empty', 'ideas'];
  for (const id of ids) {
    els[id] = makeEl('*');
    if (['error', 'success', 'empty'].includes(id)) els[id]._hidden = true; // markup ships hidden
  }
  const getQueue = [];
  const postQueue = [];
  const document = {
    getElementById(id) { return els[id]; },
    createElement() { return makeEl('article'); },
  };
  function response(status, payload) {
    return { ok: status >= 200 && status < 300, status, json: async () => payload };
  }
  function fetch(url, opts) {
    if (opts && opts.method === 'POST') {
      return new Promise((res, rej) => postQueue.push({ res, rej, response }));
    }
    return new Promise((res, rej) => getQueue.push({ res, rej, response }));
  }
  const context = { document, fetch, console, setTimeout, Date, isNaN, String, Set, Map, Array };
  vm.createContext(context);
  vm.runInContext(code, context);
  return { els, getQueue, postQueue };
}

const tick = () => new Promise((r) => setTimeout(r, 1));
async function submit(els, postQueue, title, description, scenario = '') {
  els['f-title'].value = title;
  els['f-desc'].value = description;
  els['f-scenario'].value = scenario;
  els['idea-form'].handlers.submit({ preventDefault() {} });
  await tick();
}
function idea(id, mins, extra = {}) {
  return { id, title: '相同标题', description: '相同说明', scenario: '', createdAt: new Date(Date.UTC(2026, 0, 1, 0, mins)).toISOString(), ...extra };
}
function ids(listEl) { return listEl.children.map((c) => c.datasetId || c._id); }
// tag rendered nodes: renderIdea copies fields onto element? No — we infer order via time.dateTime.
function times(listEl) { return listEl.children.map((c) => c.children.filter((k) => k.tag === '*' && k.dateTime).map((k) => k.dateTime)[0]); }

// A: submit while initial GET pending; later GET includes the submitted id (dedup by id)
{
  const { els, getQueue, postQueue } = env();
  assert(getQueue.length === 1, 'A: initial GET fired on load');
  await submit(els, postQueue, '相同标题', '相同说明');
  assert(postQueue.length === 1, 'A: POST sent while GET pending');
  const x = idea('x1', 5);
  postQueue.shift().res(response(201, { idea: x }));
  await tick();
  assert(els['ideas'].children.length === 1, 'A: new idea shown immediately after POST success');
  assert(els['empty'].hidden === true, 'A: empty note hidden after submit');
  assert(/已保存/.test(els['success'].textContent), 'A: success says saved');
  const old = idea('old', 1);
  getQueue.shift().res(response(200, { ideas: [x, old] }));
  await tick();
  const t = times(els['ideas']);
  assert(els['ideas'].children.length === 2, 'A: no duplicate when initial list also contains the idea (got ' + t.length + ')');
  assert(t[0] === x.createdAt && t[1] === old.createdAt, 'A: order newest-first');
  assert(els['empty'].hidden === true, 'A: empty note stays hidden');
}

// B: initial GET taken before submit (snapshot lacks new idea), resolves AFTER success
{
  const { els, getQueue, postQueue } = env();
  await submit(els, postQueue, '相同标题', '相同说明');
  const x = idea('x2', 9);
  postQueue.shift().res(response(201, { idea: x }));
  await tick();
  getQueue.shift().res(response(200, { ideas: [idea('old2', 0)] }));
  await tick();
  const t = times(els['ideas']);
  assert(t.length === 2 && t[0] === x.createdAt, 'B: confirmed new idea retained even though initial snapshot lacked it');
  assert(els['empty'].hidden === true, 'B: no empty note');
}

// C: initial GET returns empty AFTER a successful submit -> late empty must not show the hint
{
  const { els, getQueue, postQueue } = env();
  await submit(els, postQueue, '相同标题', '相同说明');
  const x = idea('x3', 3);
  postQueue.shift().res(response(201, { idea: x }));
  await tick();
  getQueue.shift().res(response(200, { ideas: [] }));
  await tick();
  assert(els['ideas'].children.length === 1, 'C: submitted idea still shown after late empty response');
  assert(els['empty'].hidden === true, 'C: late empty response does not reveal 还没有意见记录');
  assert(els['empty'].textContent !== '意见列表加载失败，请稍后刷新重试。', 'C: no failure wording');
}

// D: initial GET genuinely empty and resolves BEFORE any submit -> original empty hint
{
  const { els, getQueue } = env();
  getQueue.shift().res(response(200, { ideas: [] }));
  await tick();
  assert(els['ideas'].children.length === 0, 'D: nothing rendered for empty list');
  assert(els['empty'].hidden === false, 'D: empty hint visible');
  assert(els['empty'].textContent === '还没有意见记录。', 'D: original empty wording preserved');
}

// E: pending GET must not read as "no records"
{
  const { els } = env();
  assert(els['empty'].hidden === true, 'E: no empty hint while initial request in flight');
}

// F: initial GET fails after successful submit
{
  const { els, getQueue, postQueue } = env();
  await submit(els, postQueue, '相同标题', '相同说明');
  const x = idea('x4', 7);
  postQueue.shift().res(response(201, { idea: x }));
  await tick();
  getQueue.shift().res(response(500, { error: 'boom' }));
  await tick();
  assert(els['ideas'].children.length === 1, 'F: submitted idea stays visible when list load fails');
  assert(els['empty'].hidden === false, 'F: failure note shown');
  assert(els['empty'].textContent === '意见列表加载失败，请稍后刷新重试。', 'F: list-load failure wording (refresh retry preserved)');
  assert(/已保存/.test(els['success'].textContent), 'F: success message still says saved, not submission failure');
  assert(els['error'].hidden === true, 'F: submit not reported as error');
}

// G: initial GET fails before submit; submit later succeeds
{
  const { els, getQueue, postQueue } = env();
